import type { Metadata } from "next";
import { withOg } from "@/lib/shared/pageMetadata";
import {
    PaperLayout,
    PaperSection,
    PaperSubsection,
    PaperRun,
    PaperRemark,
} from "@/components/papers/PaperLayout";
import { Math } from "@/components/papers/Math";
import { StackedBondChainFigure } from "@/components/figures/StackedBondChainFigure";
import { ProcessTopologyFigure } from "@/components/figures/ProcessTopologyFigure";
import { KERNEL_EQUILIBRIUM } from "@figaro-protocol/sdk";

// The worked examples render their figures from the equilibrium module
// (the SDK's equilibrium owner), the one owner of the numbers; every other figure
// below is arithmetic over them, done here once rather than retyped in prose.
const EX = KERNEL_EQUILIBRIUM.example;
const CH = KERNEL_EQUILIBRIUM.example.chain;
// The bilateral example is a root order: G = P.
const EX_P = EX.payment;
const EX_G = EX.payment;
const EX_SELLER_PAYOUT = 2 * EX_G + EX_P;
const EX_BUYER_PAYOUT = EX_P;
// The chain example, seller by seller in commit order.
const CH_SELLERS = CH.legs.map((leg, i) => {
    const G = CH.cumulative[i];
    return {
        label: `Seller ${i + 1}`,
        P: leg.payment,
        G,
        sellerBond: CH.seller_bonds[i],
        buyerBond: CH.buyer_bonds[i],
        rho: CH.seller_bonds[i] / leg.payment,
        gap: leg.payment + G,
    };
});
const [CH_FIRST, CH_SECOND, CH_LAST] = CH_SELLERS;
// Retention under a line arrangement where the last seller's own contribution is
// a service it has not rendered: it holds what reached it, G before its order.
const CH_LAST_HELD = CH_LAST.G - CH_LAST.P;
const CH_LAST_EXPOSURE = CH_LAST.P + 2 * CH_LAST.G;
const CH_LAST_FLIP = CH_LAST_EXPOSURE - CH_LAST_HELD;
// (`Math` here is the paper's formula component, so the minimum is a reduce.)
const CH_MIN_GAP = CH_SELLERS.reduce((m, s) => (s.gap < m ? s.gap : m), CH_SELLERS[0].gap);
// The same three payments committed in another order: the ratio may fall.
const CH_REORDERED = [CH.legs[1].payment, CH.legs[2].payment, CH.legs[0].payment];
const CH_REORDERED_G = CH_REORDERED.map((_, i) => CH_REORDERED.slice(0, i + 1).reduce((s, p) => s + p, 0));
const CH_REORDERED_LAST_RHO = (2 * CH_REORDERED_G[2]) / CH_REORDERED[2];
const fmtRatio = (x: number) => (Number.isInteger(x) ? String(x) : x.toFixed(1));

export const metadata: Metadata = withOg({
    title: "Asymmetric Bonding and Buyer Dominance — Figaro Protocol",
    description:
        "Two calls, each a mechanism design of its own, make performance self-enforcing between strangers along a process chain of any length the network resolves in one call. Commit, under asymmetric bonding, locks twice the payment from the buyer and twice the cumulative value from each seller, so a defector credited with everything it keeps is still out of pocket; resolve, under buyer dominance with atomic resolution, closes every order at once on the buyer's authority and induces a weakest-link subgame among sellers. A formal mechanism-design treatment.",
});

